<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateAsset\Application\Usecase\Enable;

use RuntimeException;
use Civi\Lughauth\Features\Document\TemplateAsset\Domain\TemplateAsset;
use Civi\Lughauth\Shared\Exception\ConstraintException;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFail;

class TemplateAssetEnableCheck
{
    public function __construct(public readonly TemplateAsset $current)
    {
    }
    public function reject(RuntimeException|ConstraintFail $fail): void
    {
        if ($fail instanceof ConstraintFail) {
            throw ConstraintException::ofFail($fail);
        } else {
            throw $fail;
        }
    }
}
